"""Isolated Fish setup probe using bodies generated by the actual Kotlin FishPlan.

Creates one uniquely named test tool, test agent and no-audio session, then ends
the session and removes only created resources after verifying their identity.
The provider retains session history. No real guest data or user resources are
read, changed, or deleted. No credentials, join tickets or response bodies log.
"""
import json
import http.client
import logging
import os
from pathlib import Path
import re
import secrets
import sys

import asyncio
import time
from livekit import rtc

logging.disable(logging.CRITICAL)

def request(method, path, key, body=None):
    connection = http.client.HTTPSConnection("api.fish.audio", timeout=20)
    try:
        headers = {"Authorization": "Bearer " + key}
        if body is not None:
            headers["Content-Type"] = "application/json"
        connection.request(method, path, json.dumps(body) if body is not None else None, headers)
        response = connection.getresponse()
        raw = response.read(65536)
        try:
            payload = json.loads(raw)
        except (ValueError, UnicodeDecodeError):
            payload = None
        return response.status, payload
    finally:
        connection.close()


def sanitized_validation(payload):
    # Never print provider input, arbitrary bodies, or exception text.
    allowed = {"body", "name", "tool_type", "description", "arguments", "expects_response",
               "execution_mode", "url", "method", "value_error", "type_error", "string", "type", "missing"}
    entries = payload if isinstance(payload, list) else payload.get("detail", []) if isinstance(payload, dict) else []
    if not isinstance(entries, list):
        entries = []
    for item in entries[:20]:
        if not isinstance(item, dict):
            continue
        loc = item.get("loc", [])
        safe_loc = [str(part) if isinstance(part, int) or part in allowed else "other" for part in loc] if isinstance(loc, list) else []
        kind = item.get("type")
        kind = kind if isinstance(kind, str) and re.fullmatch(r"[a-z_]{1,40}", kind) else "other"
        print("validation location=" + ".".join(safe_loc) + " type=" + kind)
    if isinstance(payload, dict):
        print("response_fields=" + ",".join(sorted(k for k in payload if k in {"status", "message", "reason", "detail"})))
    # Classify fixed vocabulary only; never emit the server's text.
    messages = []
    if isinstance(payload, dict):
        messages.extend(payload.get(k, "") for k in ("message", "reason", "detail"))
    messages.extend(item.get("msg", "") for item in entries if isinstance(item, dict))
    text = " ".join(value.lower() for value in messages if isinstance(value, str))
    for term in ("execution_mode", "client", "webhook", "fire_and_forget", "duplicate", "name", "arguments", "description", "url", "method", "required"):
        if term in text:
            print("validation mentions " + term)


def ident(value):
    return value if isinstance(value, str) and re.fullmatch(r"[A-Za-z0-9_-]{1,128}", value) else None


def ensure(stage, status, data, expected):
    print(stage + " HTTP " + str(status), flush=True)
    if status not in expected:
        if status == 422:
            sanitized_validation(data)
        raise RuntimeError(stage + " failed")
    return data


async def check_turns(ticket, tool_name):
    room = rtc.Room()
    reports = asyncio.Queue()
    @room.on("data_received")
    def receive(packet):
        if packet.topic != "agent-event":
            return
        try:
            event = json.loads(packet.data)
            if event.get("type") == "client_tool.call" and event.get("toolName") == tool_name:
                reports.put_nowait(event.get("params", {}))
        except (ValueError, TypeError):
            pass
    readers = set()
    async def drain(reader):
        await reader.read_all()
    def consume(reader, participant):
        task = asyncio.create_task(drain(reader))
        readers.add(task)
        task.add_done_callback(readers.discard)
    room.register_text_stream_handler("lk.transcription", consume)
    start = time.monotonic()
    try:
        await room.connect(ticket["livekit_url"], ticket["token"])
        # Wait for the actual agent rather than losing the first message during its boot.
        deadline = time.monotonic() + 25
        while not any(p.attributes.get("lk.agent.state") in ("listening", "idle")
                      for p in room.remote_participants.values()):
            if time.monotonic() > deadline:
                raise RuntimeError("synthetic agent not ready")
            await asyncio.sleep(.1)
        print("synthetic_transport_ready_ms=" + str(round((time.monotonic() - start) * 1000)), flush=True)
        turns = [
            ("en", "I need a quiet room for two nights."),
            ("es", "Tenemos una habitación tranquila en la segunda planta."),
            ("es", "El desayuno se sirve a las ocho de la mañana."),
            ("en", "Please keep my reservation for two nights."),
            ("en", "Can I leave my luggage at reception tomorrow?"),
            ("und", "મને બે રાત માટે એક શાંત રૂમ જોઈએ છે."),
            ("es", "Puede dejar su equipaje aquí hasta mañana."),
        ]
        for index, (language, original) in enumerate(turns):
            await room.local_participant.publish_data(json.dumps({"type": "user.message", "text": original,
                "audio": False}).encode(), reliable=True, topic="client-event")
            report = await asyncio.wait_for(reports.get(), timeout=20)
            actual = report.get("source_language")
            translated = report.get("translation")
            passed = actual == language and isinstance(translated, str) and bool(translated.strip()) == (language != "und")
            passed &= report.get("original") == original
            print("synthetic_turn=" + str(index + 1) + " expected_language=" + language + " passed=" + str(passed).lower(), flush=True)
            if not passed:
                # Only this fresh, isolated room receives these fixed synthetic phrases.
                # Do not log arbitrary API responses, tickets, headers or exception text.
                print("synthetic_caption=" + json.dumps({name: str(report.get(name, ""))[:500]
                    for name in ("source_language", "original", "translation")}, ensure_ascii=True), flush=True)
                raise RuntimeError("synthetic language routing failed")
        print("scope=text_input_only_no_microphone_no_acoustic_latency_claim", flush=True)
    finally:
        await room.disconnect()


def main():
    key = os.environ.get("FISH_API_KEY", "").strip()
    if not key or len(sys.argv) != 2:
        print("Missing secret or fixture path", file=sys.stderr)
        return 1
    nonce = secrets.token_hex(12)
    tool_name = "qa_caption_" + nonce
    agent_name = "qa_interpreter_" + nonce
    end_user_id = "qa_session_" + nonce
    owned_tool = owned_agent = owned_session = None
    tool_attempted = agent_attempted = session_attempted = False
    success = False
    try:
        plan = json.loads(Path(sys.argv[1]).read_text())
        tool = json.loads(Path("android/hotel/src/main/assets/fish-caption-tool.json").read_text())
        tool["name"] = tool_name
        tool.pop("execution_mode", None)
        tool_attempted = True
        status, data = request("POST", "/v1/agent/tools", key, tool)
        if 400 <= status < 500 and status != 408:
            tool_attempted = False
        data = ensure("tool_create", status, data, (200, 201))
        owned_tool = ident(data.get("tool_id")) if isinstance(data, dict) else None
        if not owned_tool:
            raise RuntimeError("synthetic tool identifier missing")
        tool_attempted = False
        config = plan["config"]
        assert config["tools"]["tool_ids"] == ["synthetic-tool-id"]
        config["tools"]["tool_ids"] = [owned_tool]
        config["prompt"]["system_prompt"] = config["prompt"]["system_prompt"].replace(
            "manzanilla_publish_interpretation_v2", tool_name)
        agent = {"name": agent_name, "description": "Isolated synthetic interpreter test", "config": config}
        agent_attempted = True
        status, data = request("POST", "/v1/agent/agents", key, agent)
        if 400 <= status < 500 and status != 408:
            agent_attempted = False
        data = ensure("agent_create", status, data, (200, 201))
        owned_agent = ident(data.get("agent_id")) if isinstance(data, dict) else None
        if not owned_agent:
            raise RuntimeError("synthetic agent identifier missing")
        agent_attempted = False
        status, data = request("POST", "/v1/agent/agents/" + owned_agent + "/publish", key, {})
        ensure("agent_publish", status, data, (200, 201))
        session = plan["session"]
        assert session["agent_id"] == "synthetic-agent-id" and session["record_audio"] is False
        session["agent_id"] = owned_agent
        session["overrides"]["system_prompt"] = session["overrides"]["system_prompt"].replace("manzanilla_publish_interpretation_v2", tool_name)
        session["end_user_id"] = end_user_id
        session_attempted = True
        status, data = request("POST", "/v1/agent/sessions", key, session)
        if 400 <= status < 500 and status != 408:
            session_attempted = False
        data = ensure("session_create", status, data, (200, 201))
        owned_session = ident(data.get("session_id")) if isinstance(data, dict) else None
        if not owned_session:
            raise RuntimeError("synthetic session identifier missing")
        session_attempted = False
        if data.get("transport") != "livekit" or not str(data.get("livekit_url", "")).startswith("wss://") or not data.get("token"):
            raise RuntimeError("session transport unavailable")
        print("transport_fields_present=true", flush=True)
        asyncio.run(asyncio.wait_for(check_turns(data, tool_name), timeout=175))
        success = True
    except Exception:
        # Provider and transport error text can contain private details.
        print("Synthetic setup did not complete; checking owned-resource cleanup", file=sys.stderr, flush=True)
    finally:
        clean = not (tool_attempted or agent_attempted or session_attempted)
        if owned_session:
            try:
                status, _ = request("POST", "/v1/agent/sessions/" + owned_session + "/end", key, {})
                print("session_end HTTP " + str(status), flush=True)
                clean &= status == 204
            except Exception:
                clean = False
        if owned_agent:
            try:
                status, data = request("GET", "/v1/agent/agents/" + owned_agent, key)
                if status != 200 or not isinstance(data, dict) or data.get("name") != agent_name:
                    raise RuntimeError("synthetic agent identity not verified")
                status, _ = request("DELETE", "/v1/agent/agents/" + owned_agent, key)
                print("agent_cleanup HTTP " + str(status), flush=True)
                clean &= status == 204
            except Exception:
                clean = False
        if owned_tool:
            try:
                status, data = request("GET", "/v1/agent/tools/" + owned_tool, key)
                if status != 200 or not isinstance(data, dict) or data.get("name") != tool_name:
                    raise RuntimeError("synthetic tool identity not verified")
                status, _ = request("DELETE", "/v1/agent/tools/" + owned_tool, key)
                print("tool_cleanup HTTP " + str(status), flush=True)
                clean &= status == 204
            except Exception:
                clean = False
        if not clean:
            print("Synthetic cleanup needs investigation; name suffix " + nonce, file=sys.stderr, flush=True)
        return 0 if success and clean else 1


if __name__ == "__main__":
    raise SystemExit(main())
